(@base+233, @formulario, 'Dotación de espacios para el desarrollo de las actividades académico administrativas', @anio, (SELECT linea FROM tmp_lmp_2023 WHERE lc = 'L5' AND mc = 'M3' AND pc = 'P5'), (SELECT objetivo FROM tmp_lmp_2023 WHERE lc = 'L5' AND mc = 'M3' AND pc = 'P5'), '9. Fortalecer la administración y ejecución de los planes, programas y proyectos propendiendo por el desarrollo de las actividades misionales fundamentada en principios de eficiencia, transparencia, equidad y calidad de servicio.', (SELECT motor FROM tmp_lmp_2023 WHERE lc = 'L5' AND mc = 'M3' AND pc = 'P5'), 'Alcanzar al menos el 70% de los espacios dotados adecuadamente para el desarrollo de las actividades académico administrativas con base en las necesidades identificadas.', (SELECT proyecto FROM tmp_lmp_2023 WHERE lc = 'L5' AND mc = 'M3' AND pc = 'P5'), 1.00, 'Gestionar la dotación de espacios para el desarrollo de las actividades académico administrativas de acuerdo a las necesidades identificadas', 100.00, 'Oficina de Planeación', 'PA', '0', 'Dotación de espacios para el desarrollo de las actividades académico administrativas', '(N° de espacios dotados según requerimientos / N° de espacios proyectados a mejorar) * 100', 'Anual', 'Porcentaje', 'Último valor reportado', '', '["Plan Anual de Adquisiciones"]', '7%', 30, '0%', '30%', '30.00', @ef, 0, IF(@ef=2,1,0), 0, IF(@ef=2,4,0), 0, 0, 0, IF(@ef=2,NOW(),NULL), 1);
INSERT INTO formulacion_144 (id, formulario_id, nombre_borrador, anio, linea_estrategica, objetivo, estrategia, motor_desarrollo, meta_resultado, proyecto, ponderacion_proyectos, actividad_proyecto, ponderacion_actividades, responsable_formulacion, id_indicador, gestionado_facultades, nombre_indicador, formula_medicion, frecuencia_medicion, unidad_medida, tipo_medicion, descripcion_indicador, planes_institucionales, linea_base_meta, anio_base_meta, meta_s1, meta_s2, meta_programada, estado_formulacion, estado_seguimiento, solicitud_estado_formulacion, solicitud_estado_seguimiento, semaforo_etapa_formulacion, semaforo_etapa_seguimiento, semaforo_rechazo_etapa_formulacion, semaforo_rechazo_etapa_seguimiento, fecha_publicacion_formulacion, creado_por)
INSERT INTO tmp_seg_2023 (n, t2, t4, s1, s2, ejecutada, avance, logros, limites, observacion, acciones) VALUES
(1, '0', '1', 0.00, 1.00, 1.00, 100.00, 'Desde el Programa de Formación Docente de la Vicerrectoría de Docencia se abrió en el mes de septiembre la convocatoria Bilinguismo 2023 para que los docentes de planta se inscriban en los cursos de ingles que se ofertaran con ayuda de Cursos Libres de Lenguas Extranjeras del Departamento de Extension y Proyeccion Social.\n El docente para poder acceder a estos cursos deberá además, de ser docente de planta realizar un examen diagnóstico clasificatorio (42 docentes tomaron la prueba de los cuales )solo el 4,7% tiene conocimientos intermedios, el 11,9% tiene bases de vocabulario y el 16,7% manejo basico de estructuras y el 38% no maneja el idioma ingles).\n Se realizaron pruebas diagnosticas, posterior a esto se inicio el curso en nivel A1', '', '', ''),
(2, '13', '5', 13.00, 5.00, 18.00, 105.88, 'Para el semestre 2023-1, desde las actividades realizadas con la Oficina ORII desde el componente de Multilingüismo e Interculturalidad se han realizado lo siguiente: 3 clubes conversacionales del idioma Francés como básico, Intermedio y Avanzado; impactando a la comunidad educativa y a las diferentes falcultades de la universidad: como Ciencias Humanas 15 estudiantes de los diferentes programas academicos de los cuales Filosofía(6 estudiantes), Historia(2 estudiantes) y Sociología (5 estudiantes). Facultad de Ciencias Juridicas programa de Derecho (6), Facultad de Educación Licenciatura 12 estudiantes de los cuales se descriminan de la asiguiente manera en Lenguas Extranjeras con énfasis en Ingles y Francés (4) Licenciatura en Matemanticas (3) Licenciatura en Educación artistica (3) y Licenciatura en Ciencias Sociales (2), Facultad de Ciencias Básicas 5 estudiantes que se distribuye de la siguiente manera: Matematicas (3) Biología (1) y Fisica (1), donde logramos establecer las relaciones culturales con el idioma francofono. Se realizo de forma exitosa para los estudiantes del programa de Licenciatura en Lenguas Extranjeras con 6 talleres de fonetica del idioma de Francés para afianzar los conocimientos propios del idioma a través de diferentes actividades. Una de estas actividades tuvimos un alcance regional en la sede Suan con los estudiantes del programa en mencion. \nSe realizo conjunto con la Universidad del Sur de California actividades del CLUB CONVERSACIONAL en el idioma español, para los estudiantes que realizaron su movilidad entrante internacional beneficiados con la beca de 100,000 STRONG IN THE AMERICAS. Otras de las actividades con compenten multilingue que se alcanzo en este primer semestre del año 2023, fueron las actividades del Tandem virtual de Aleman con la Universidad de Hanover en país de Alemania, promoviendo así la diversidad cultural de los ambos paises con los estudiantes de la Universidad del Atlántico y la Universidad extranjera. El 29 de mayo, conjunto con universidades regionales y la secretaria de educación departamental del Atlantico, la Oficina de Relaciones Interintitucionales e Internacionales y el programa de Lic. En Lenguas Extranjeras se recibio visita de la Universidad el Bridgwater University la delegación de 10 estudiantes y 1 docente para observación en el departamento de como se imparte los conocimientos de las lenguas extranjeras, tambien se realizo conferencia de "Enseñanzas de las lenguas a nivel global" Visita de la Universidad el Sur de Califonia , se realiza conferencia en conjunto con la Universidad del Sur de California para la facultad de Quimica y Farmací: Pharmacy Education and practice in the united states, Periodo 2023-2: \nPERIODO III TRIMESTRE: Para la realización de seguimiento del indicadicador con el componente multilingüe en el semestre del año 2023-II, se han realizado las siguientes actividades: 1. PICNIC con el grupo AEKCO (Alianza de Estudiantes de Koika-Colombia), con el animó de fortalacer la cultura coreana en la Universidad del Atlántico. Con esta actividadad se impacto a estudiantes de diferentes facultades y programas academicos. 2. Se realiza el E-TANDEM virtual del idioma Aléman en conjunto con la Universidad de Hannover en el país de Alemania, esto con el fin de realizar actividades en pro de multilingüismo e interculturalidad del programa de Licenciatura en Lenguas Extranjeras con énfasis en Inglés y Francés. 3. Se realizo la actividad de Hangeul-NAL, con el acompañamiento de los estudiantes inscritos en el grupo AEKO (donde se resalto temas culturales importantes, como sus costumbres, idiomas, comida etc), esta actividad liderada por la Oficina ORII y el grupo AEKO, tuvo un gran impacto en las 10 facultades de la Universidad, mediante sus staff. 4. Con la coordinación de Programa de Licenciatura en Lenguas Extranjeras se realizo EXPODEUTSCHLAND 2023- donde los estudiantes de Licenciatura de Lenguas Extranjeras realizaron muestra culturales de la cultura alemana. 5. En el mes de octubre se realizo con los estudiantes de Licenciatura en Lenguas Extranjeras con énfasis en Inglés y francés con los estudiantes beneficairios de la convocatoria de inmersión el evento de PRE-DEPARTURE, donde contamos con diferentes docentes de la Universidad Dalhouise.', 'Encontramos que los estudiantes de la comunidad universitaria no culminan las activiadades de los diferentes idiomas, que ofrece la Universidad del Atlántico en pro de la interculturalidad, o no asisten a los diferentes eventos.', 'Se cumple la meta establecida para el año 2023.', 'Para el añ0 2024, se pretende seguir promoviendo las activadades con componente multilingë a través de diferentes eventos y actividades.'),
(3, '259', '172', 259.00, 172.00, 431.00, 53.87, '259 estudiantes culminaron el curso de ingles establecido por la politica de enseñanza aprendizaje y evaluacion de lenguas extranjeras (nivel B2.1) de 306 estudiantes que estaban matriculados.\n\nPara el segundo semestre del 2023, 172 estudiantes culminaron el curso de ingles de 183 estudiantes que estaban matriculados.', '', '', ''),
(4, '0', '30', 0.00, 30.00, 30.00, 120.00, 'El 28 de octubre viajaran a Halifax, 30 estudiantes del programa de Licenciatura en lenguas extranjeras de la facultad de Educación, bajo el programa de inmersión de idiomas de la Universidad del Atlántico.', 'Se debe realizar la preorización de los recursos economicos a través de las diferentes instancia superiores de la Universidad del Atlántico para realizar este tipo de movilidad para los estudiantes de Licenciatura de Lenguas Extranjeras. Esto con el fín de los estudiantes al culminar su inmersión en el país de habla inglesa realicen la contraprestación como docentes tutores de los diferentes niveles de la Política de Enseñanza, Aprendizaje y Evaluación de Lenguas Extranjeras.', '', 'En el 2024, se seguira impulsando conjunto con la coordinación del programa de Licenciatura de Lenguas Extranjeras con énfasis en Inglés y Francés, el programa de inmersión en diferentes Universidadades de habla inglésa para que los estudiantes puedan no solo realizar actividades academicas en pro del fortalecimiento del idioma, y que tambien tengan experencias culturales en diversos paises.'),
(5, '46', '256', 46.00, 256.00, 302.00, 2516.67, 'Se logro movilizar 1 estudiante entrante nacional de la universidad de Cartagena quien hizo proceso de intercambio académcio en el programa de derecho de la facultad de ciencias juridicas, en el periodo 2023-1.\n45 estudiantes de la Universidad de la Guajira, quienes desarrollaron actividad académica con la Facultad de Ciencias Económicas y el programa de Administración de Empresas Turisticas.\n\nIII Trimestre: 72 estudiantes de la Universidad del Magdalena hicieron movilidad para el III ENCUENTRO DE: "PROSPECTIVA DEL CONTADOR PÚBLICO A NIVEL E INTERNACIONAL" del programa de Contaduria de la Facultad de Ciencias Económicas, 10 estudiantes entrantes de la Universidad Unisinu de Cartagena para actividad académica con los programa de contaduria publica y economia.', 'Faltan movilidades por reportar ante la ORII, por las diferentes facultades y vicerrectrias.', '', ''),
(6, '936', '762', 936.00, 762.00, 1698.00, 42450.00, '9 estudiantes del propgrama de contaduria de la facultad de Ciencias Economics, que se movilizaron al I Congreso Nacional Estudiantil en Contabilidad, Interés Público y Bienestar Social, realizado en cartagena, 47 estudiantes del programa de Licenciatura de Educación especial de la Facultad de Educación, en misión académica con la Fundación del Rosario en Cartagena, para conocer procesos inclución, 35 estudiantes del programa de Historia, de la Facultad de Ciencias Humanas, salieron a misión académica a museos y fortificaciones historicas en Cartagena,18 estudiantes del programa de Nutrición y dietetica asistieron a traves de curso de extensión a Santa Marta para el curso de Curso de Elaboración de Chorizo de Pescado, 7 estudiantes bajo modalidad de prácticas en el Hospital Universitario Julio Méndez Barreneche en Santa Martha, 3 estudiantes se movilizaron para los Juegos Universitarios Regionales 2023 en valledupar, 20 estudiantes de la sede suan hicieron misión académica con Salida de campo con el objetivo de realizar visita a empresas de procesamiento de frutas y verduras en Cartagena. A traves de bienestar se reportan 756 movilidades ( 15 de Arquitecturas para eventos académicos,86 de facultad de Bellas Artes a eventos académicos, 42 facultad de Ciencias basicas, 90 Facultad de Educación,73 Facultad de Ciencias Económicas, 104 Facultad Ciencias Humanas,46 Facultad de Ciencias Juridícas,191 facultad de Ingenieria, 92 facultad de Nutrición y dietetica, 17 Facultad de Quimica y Farmacia), de la Facultad de Ciencias Basicas se movilizarón 17 estudiantes(VI Congreso colombiano de zoologia, l 66 o Congreso Internacional que realizará la Asociación Colombiana de Ingeniería Sanitaria y Ambiental – ACODAL, "Colombianísimo Congress") Facultad de Arquitectura 2 estudiantes en proceso de intercambio académico, facultad de ingenieria 2 estudiantes ( 2 por misión académica ), 20 estudiantes del programa de Licemciatura en Matematicas de la Facultad de Educación( 15 asistieron al evento 4 Encuentro Internacional de Investigación e Innovación en Educación Matemática. EIII+ED+MAT, 3 en Viva la escuela y 2 docente al XIII Simposio de Matemáticas y Educación Matemática, XII Congreso Internacional de Matemática Asistida por Computador y III Simposio de Competencias Matemáticas)\n\n\nIII timetre: del programa de Quimica y farmacia de la Facultad de Quimica y Farmacia (6) estudiantes asistieron a la XXV Juegos Regionales ASCUN 2023 y (2) estudiantes en participacon cultural en Juegos Universitarios Nacionales ASCUN 2023. del programa de Licenciatura en Educación infantil de la facultad de Educación en modalidad de practica se movilizo (1) estudiantes a la Universidad del bosque, (1) estudiante del programa de Musica de la Facultad de Bellas Artes a la Universidad del Bosque para proceso de prácticas, (2) estudiantes del programa de Quimica y Farmacia de la Facultad de Quimica y Farmacia en modalidad de practicas hacia la universida del santander. (1) estudiante del programa de Arquitectura de la facultad de Arquitectura bajo intercambio académico con la Universidad Nacional de Colombia,(7) estudiantes de la Facultad de Ciencias económicas del programa de contaduria publica asistieron al evento "6to Encuentro de Pensamiento Contable: Contabilidad, Ambiente y Sociedad" en la ciudad de Manizales, (5) estudiantes del programa de económia participaron en el evento académico Congreso Anual de la Red de investigadores de Economía 2023 “MERCADOS LABORALES: CAPITAL HUMANO, IGUALDAD DE OPORTUNIDADES, FORMALIZACIÓN Y TRANSFORMACIÓN PRODUCTIVA” realziado con la Universidad de Medellin en la ciudad de Medellin, (3) estudiantes participaron en el evento académico LXX ASAMBLEA NACIONAL ORDINARIA DE DELEGADOS DE LA FEDERACIÓN NACIONAL DE ESTUDIANTES DE ECONOMÍA, realizado en Valledupar cesar.', 'Faltan movilidades por reportar ante la ORII, por las diferentes facultades y vicerrectrias.', '', ''),
(7, '19', '12', 19.00, 12.00, 31.00, 103.33, 'Se lograron movilizar 19 estudiantes discriminados de los siguientes programas: \n1 estudiante de la Universidad Illinois Estados Unidos en el programa de Licenciatura Lenguas extranjeras.\n1 estudiante de la Universidad Nacional San Juan de Argentina del programa de Ingenieria Quimica de la Facultad de Ingenieria, beneficiario de la convocatoria PILA 2023-1.\n1 estudiante de la Universidad de Valencia España, para el programa de Nutrición y Dietetica en proceso de prácticas.\n6 estudiantes procedentes de la Universidad del Sur de califonia para actividad académica con la Facultad de Quimica y Famarcia\n10 estudiantes entrantes de la Universidad state Bridgewater, de los estados unidos, vinieron para actividad académica con la facultad educación y el programa de Licenciatura de lenguas extranjeras.\n\n\nIII timetre: En procesos de intercambio académico, en los programas de: (1) estudiante de Arquitectura de la Facultad de Arquitectura, (1) en Administración de Empresa de la Facultad Ciencias Economicas , (1) en Historia de la facultad de Ciencias Humanas y (1) Licenciatura en Humanidades y lengua castellana de la Facultad de Edcuación, (8) estudiantes de la Facultad de Ciencias Juridicas del programa de derecho , quienes nos visitaron de la Universidad San Gregorio de Porto viejo Ecuador, para el X olimpiadas jurídicas de la Universidad del Altlántico', 'Faltan movilidades por reportar ante la ORII, por las diferentes facultades y vicerrectrias.', '', ''),
(8, '20', '51', 20.00, 51.00, 71.00, 177.50, '7 estudiantes beneficiados de la convocatoria expertos internacionales del ICETEX, viajaron a chile para movilidad académica.\n2 estudiantes del programa de Ingenieria Mecánica, de la Facultad de Ingenieía realizaron movilidad académcia por intercambio académico.\n5 estudiantes del programa de Quimica y Farmacia realizaron movilidad académica con el curso de invierno con la Universidad Sur de Califonia.\n4 estudiantes del programa de Quimica y Farmacia realizaran movilidad académcia con la Universidad del Sur de Califonia.\n\n1 estudiante del programa de Filosofía de la Facultad de Ciencias Humanas beneficiado de la Convocatoria PILA 2023-1, realizó movilidad académica de Intercambio académico con la Universidad Nacional de san Juan de Argentina.\n1 estudiante del programa de derecho de la Facultad de Ciencias Juridicas realizo intercambio académcio con la Universidad de Hidalgo México.\n\nIII Trimestre: se registraron las siguientes movilidades, 1 estudiante del programa de ingenieria de la Facultad de Ingenieria quimica realizo estancia de investigación con la Universidad McGill University en Canadá bajo convcoatoria Mitacs de la embajada de Canadá, 1 estudiante en proceso de Intercambio académico con la Universidad Salamanca-España del programa de ingenieria quimica de la facultad de Ingenieria ,10 estudiantes del programa de Artes Plasticas de la Facultad de Bellas Artes beneficiarios de la Beca DAAD bajo el programa de becas Study Visits by Groups of Foreign Students, 1 estudiante del programa de Licenciatura en Educacuón Infantil de la Facultad de Educación en proceso de practicas con la Universidad Católica de Salta Argentina, 30 estudiantes del programa de Linceciatura de Lenguas Extranjeras de la Facultad de Educación bajo el programa de inmersión de idiomas de la Universidad del Atlántico, 3 estudiantes del programa de derecho de la facultad de Ciencias Juridicas, en mision academica en chile bajo la convocatoria de Red Iberoamericana de derecho.', 'Faltan movilidades por reportar ante la ORII, por las diferentes facultades y vicerrectrias.', '', ''),
(9, '14', '18', 14.00, 18.00, 32.00, 160.00, 'Se realizan Dos (2) movilidades de la facultad de educación, programa de Lic. en Educación Especial en el marco de la movilidad internacional a Chile del proyecto Subvenciones 2022 del ICETEX con el programa de diverser de la UA. Uno (1) de la Facultad de Ingenierias, programa de Ingenieria Química en el marco de la convocatoria de Silicon Valley a EEUU. dos (2) de la facultad de Ciencias Humanas con un movilidad a Alemania y a Madrid españa. Una (1) docente de Bellas Artes a la Habana - Cuba en el marco de una estancia académica. Una (1) movilidad administrativa por parte del rector de la UA a Europa en una misión académica). (1) docente de la facultad de Arquitectura como ponente en el evento Simposio caribeño y amazonico sobre materiales sostenibles. (6) docentes de la facultad de Ciencias Basicas se movilizaron como estancia investigativa y poenencia en estados unidos, Chile, mexico, italia y Reino Unido, \n\n2 saliente internacional del programa de economia (uno por IV Congreso Internacional, XI Encontro Rural Repor y XVIII Congreso de Historia Agraria en la Universidade de Coimbra en portugal y Estancia para atender reunión de Comités y de seguimiento de Redes y Proyectos CYTED en marco de la Red RITMMA, en santiago de chile.) 5 saliente internacional Ciencias Humanas (tres para el IV Congreso Internacional, XI Encontro Rural Repor y XVIII Congreso de Historia Agraria,dos para 44° Versión Simposio internacional Wittgenstein) 1 saliente internacional de Licenciatura de lenguas extranejras con el programa de inmersión de lenguas extraneras en la Universidad Dallhousie en Canadá.,1 saliente internacional de programa de Artes plasticas beneficiario de la Beca DAAD a traves del becas Study Visits by Groups of Foreign Student en Alemania.', 'Dentro de los límites más significativos para la medición y cumplimiento del indicador, debemos resaltar que no todas las facultades han realizados los reportes pertinentes.', 'Dentro de los logros obtenidos podemos ver que el indicador lleva una tendencia al cumplimiento de la meta, en el III trimestre solo falta 2 movilidades para cumplir la meta semestral de este. Esto quiere decir que con las movilidades registradas entre octubre y diciembre el indicidor alcanzará la meta.', ''),
(10, '22', '30', 22.00, 30.00, 52.00, 260.00, 'Se realizan cuatro (4) movilidades de la facultad de Ciencias Humanas, dos (2) de Nutrición y Dietética y siete (7) de Quimica y Farmacia, 5 docentes de la Facultad de Ciencias Basicas realziaron movilidad bajo la mosalidad de estancia investigativa,asistencia a eventos académicos y ponencias en la ciudad de Santa Marta, Medellin, Bogota y Monteria. 1 docente de la Facultad de Ingenieria se movilizo como ponete expositor en Primer Encuentro Mesa Caribe de Soberanía y Seguridad Alimentaria realizado en Cartagena de Indias, de la Facultad de Educación 3 docentes del programa de Licenciatura en Matematicas se movilizaron al 4to Encuentro Internacional de Investigación e Innovación en Educación Matemática. EIII+ED+MAT realizado en Sincelejo.\n\n3 saliente nacional Economia (uno para el evento 6to Encuentro de Pensamiento Contable: Contabilidad, Ambiente y Sociedad en Manizales,dos para el I SEMANA INTERNACIONAL DE INVESTIGACIÓN: LA CONTADURÍA PÚBLICA AL SERVICIO DE LA SOCIEDAD en Bogota.) 3 Saliente nacional ciencias humanas (uno con el evento IX Seminario Internacional de Desarrollo Profesional de los Docentes de Lenguas Extranjeras & I Seminario de Desarrollo Profesional en Docencia de la Traducción y la Interpretación en Antioquia,dos con el evento Congreso internacional de filosofía: Justicia, reconocimiento y paz en la ciudad de cartagena)1 saliente nacional de quimica y farmacia con SINTRADEUA en los juegos deportivos en medellin.', '', '', ''),
(11, '17', '59', 17.00, 59.00, 76.00, 380.00, 'Se registran dieciseis (17) movilidades así: Un (1) docente a la Facultad de Bellas Artes, proveniente de España de la Universidad de Barcelona para intercambiar documentación de convenios a suscribir con ese claustro; Dos (2) a la Facultad de Ciencias Básicas provenientes de la Universidad de Sao Paulo en Brasil para realizar una estancia investigativa y realizar charla con la comunidad estudiantil; Dos (2) a la Facultad de Ciencias Humanas, programas de Filosofía e Historia, el primero proveniente de UAM de madrid, España; Seis (6) a la Facultad de Educación, progama de maestría en Neuropedagocía, para colaborar en la ejecución de IV congreso en neuropedagogía, todos estos provenientes de España, EEUU, Cuba y Argentina. Uno (1) más a la Facultad de Ingeniería, proveniente de Lima, Perú, de la Universidad de Ingeniería y Tecnología de Lima en el marco del Bonn Art gallery Exposición you+me Internacional; Se recibe una (1) movilidad administrativa, cuando el Director de Internacionalización de la UNIR visita la Rectoría en el marco de la entrega de unas becas educativas; Dos (2) a la Facultad de Quimica y Farmacia, provenientes de la Universidad del Sur de California, en el marco de la ejecución del proyecto conjunto que ha sido beneficiario de los apoyos de la convocatoria 100k. de la Facultad de Educación del programa de Licenciatura en Matematicas 2 docentes fueron a la universidad del Atlántico como ponentes en el marco del evento Escritura Científica y el evento Teaching math in context: a strategy for multilingual learners \n\nCon 16 movilidades registradas desde diferentes facultades, el indicador ha demostrado que ya cumplió. Sse debe aclarar que aun falta 3 meses para el reporte definitivo de este.', 'No se encuentran límites en este indicador ya que ha cumplido su meta.', '', ''),
(12, '0%', '22%', 0.00, 22.00, 22.00, 440.00, 'el total de Programas con asignaturas con componente internacional es de 21, las cuales son las siguientes:\n\nFacultad de Arquitectura (4)\nArquitectura\nTécnica profesional en construcción de proyectos arquitectónicos\nTécnica profesional en documentación de proyectos urbanísticos\nTécnica profesional en expresión gráfica arquitectónica\nFacultad de Bellas Artes (3)\nArte Dramático\nArtes Plásticas\nLicenciatura en Música\nFacultad de Ciencias Básicas (2)\nMatemáticas\nQuímica\nFacultad de Educación (3)\nLicenciatura en Ciencias Sociales\nLicenciatura en Educación Infantil\nLicenciatura en Matemáticas\nFacultad de Ciencias Económicas (2)\nContaduría Pública\nEconomía\nFacultad de Ciencias Humanas (3)\nSociología\nFilosofía\nHistoria\nFacultad de Nutrición y Dietética (3)\nNutrición y Dietética\nEspecialización en contratación e interventoría de servicios alimentarios a colectividades\nMaestría en Seguridad Alimentaria y Nutricional\nFacultad de Ciencias Jurídicas (1)\nDerecho\nIngenieria (0)\nQuímica y Farmacia (0)\n\nIndicador: 21 de 95 programas o el 22% de los programas tienen asignaturas con componente internacional.', '', 'La ORII en reuniones con Vicedocencia quedó en construir un documento sobre los lineamientos para internacionalizar el curriculo', ''),
(13, '6.5%', '9.4737%', 6.50, 9.47, 9.47, 189.47, '"Se han desarrollado un total de 42 Clases Espejo en el año 2023 con un total de 9 programas. Los programas que participaron fueron los siguientes: Maestria En Neuropedagogia, Contaduría, Licenciatura en Educación Fisica, Licenciatura en Educación Inclusiva, Administración de Empresas Turísticas, Quimica, Filosofía, Biologia\nLicenciatura en Educación Infantil"', 'No se nos ha facilitado la información de la base de datos completa impidiendo llegar a todos los docentes./ Falta de comunicación con los docentes ya que en repetidas ocaciones enviamos correos a los docentes inscritos y no recibimos respuesta', 'La meta se ha cumplido y sigue incrementando el numero de programas participantes', 'Se estará desarrollando actividades de socialización a las facultades que aún no han participado./Se seguira mandando correos incentivando a los programas participar.'),
(14, '20.9%', '26.3158%', 20.90, 26.32, 26.32, 526.32, 'En el año 2023 se han realizado un total de 74 eventos de los cuales en 42 eventos han participado 25 programas de la Institución. Los programas participantes son los siguientes: Ingeniería Química, Ingeniería Mecanica, Ingeniería Agroindustrial, Ingeniería Industrial, Contaduría Pública, Danza, Filosofia, Biologia, Música, Licenciatura en Ciencias Sociales, Administración de Empresas Turísticas, Química y Farmacia, Ciencias Politicas, Administración de Empresas, Licenciatura en Lenguas Extranjeras, Doctorado en Ciencias de la Educación, Maestría en Neuropedagogía, Nutrición y Dietética, Licenciatura en Educación Artistica, Licenciatura en ciencias naturales, derecho, licenciatura en humanidades y lengua castellana, Licenciatura en Educación Especial, Economia y Matematicas', 'La falta de presupuesto ha limitado eventos a desarrollarse presencialmente.', 'Se observa que se ha dado cumplimiento de la meta dle año 2023', 'Desde la ORII estaremos trabajando en la realización de actividades que impacten a la población institucional.'),
(15, '27', '34', 27.00, 34.00, 61.00, 305.00, '2023-1: \n\nArquitectura 0\nBellas Artes 3\nCiencias Básicas 1\nCiencias Económicas 5\nCiencias Humanas 0\nCiencias Jurídicas 1\nEducación 6\nIngeniería 8\nNutrición 1\nQuímica y Farmacia 2\nTotal 27\n\n\n2023-2:\n\n\nArquitectura 2\nBellas Artes 1\nCiencias Básicas 6\nCiencias Económicas 7\nCiencias Humanas 3\nCiencias Jurídicas 3\nEducación 5\nIngeniería 3\nNutrición 2\nQuímica y Farmacia 2\nTotal 34', 'Esta información depende de las respuestas de cada facultad.', 'En el primer semestre se cumplio la meta del año. 4 facultades han logrado cumplir la meta de minimo 2 eventos. Estas son la facultad de Bellas Artes, Educación, Ciencias Económicas e Ingenieria. // Las facultades de Ciencias Humanas y Ciencias Jurídicas han logrado cumplir la meta junto a las 4 facultades que lograron en el primer semestre', 'Realizar reuniones periodicas con las facultades en donde se promueva la realización de eventos y que podemos hacer desde la ORII para lograr que estos eventos puedan ser realizados. Se enfocaran estas reuniones en las facultades donde no se ha cumplido la meta.'),
(16, '23.0769%', '38.4615%', 23.08, 38.46, 61.54, 307.69, '5 lineamientos implementados: \n• Generar condiciones de acceso y permanencia a través de los ambientes virtuales de aprendizajes mediados por plataformas educativas. Este aspecto se ha implementado a partir del apoyo a los accesos a los ambientes de aprendizajes en las tres plataformas educativas (SICVI-567, SIGAP, eContinua). \n• Desarrollar procesos permanentes de actualización docentes con respecto al uso de las TICS, se ha implementado a través de los cafecitos con las TIC, dos conferencias en modalidad presencial con invitados internacionales.\n• Dinamizar el apoyo a los procesos de enseñanza y aprendizaje curricular con el uso de las TIC se han implementado tutoriales con acceso libre a todos los docentes y en el segundo semestre el desarrollo y puesta en marcha de un curso autogestionado para docentes sobre el uso de Sistemas de Gestión de Aprendizaje.\n• Apoyar la oferta de programas del nivel técnico, tecnológico, profesional y posgradual en cualquier modalidad generadas desde las Facultades. Este aspecto se cumple con el apoyo a la construcción de documentos de autoevaluación de programas (entrega de informes en el aspecto Recursos Educativos y uso pedagógico de TIC). En este semestre se apoyo la creación de un nuevo programa de pregrado en modalidad virtual sobre lengua de señas colombiana. \n• Brindar acompañamiento pedagógico a los docentes de las facultades con docentes especializados en uso pedagógico de TIC y consejerías pedagógicas virtuales, así como apoyo estudiantil con monitorías académicas presenciales o virtuales. Este aspecto se cumple en la medida que contamos con las asesorías permanentes de los Docentes Asesores de Facultad (DAF) para apoyar a los docentes y estudiantes de las diferentes facultades.', '', '', ''),
(17, '0%', '18.9474%', 0.00, 18.95, 18.95, 189.47, 'Se realizó el evento del Segundo Encuentro de Prácticas Docentes - innovación educativa mediada por las TIC. Participaron 9 facultades, 18 programas y un total de 25 experiencias de innovación.\nLos programas fueron: Arquitectura, Lic. Educación musical, Artes Plásticas, Química, Lic en matemáticas, Matemáticas, Idiomas, Lic. Educacion Infantil, Administración de Empresas, Turismo, Historia, Lic. en Educación Especial, Ciencias jurídicas, Ingeniería Industrial, Nutrición y Dietética, Biología, Contaduría Pública, Maestría en educación. Y por administrativo oficina (Diverser)', '', '', ''),
(18, '0', '25', 0.00, 25.00, 25.00, 113.64, 'Se realizó el evento del Segundo Encuentro de Prácticas Docentes - innovación educativa mediada por las TIC. Participaron 9 facultades, 18 programas y un total de 25 experiencias de innovación.\nLas facultades que fueron: Arquitectura (2), Bellas Artes (3), Ciencias Básicas (3), Ciencias de la Educación (5), Ciencias Económicas (4), Ciencias Humanas (3), Ciencias Jurídicas (1), Ingeniería (2), Nutrición y Dietética (2).', '', '', 'Se ha realizado la propuesta de la convocatoria y la solicitud del presupuesto para el evento: encuentro de practicas docentes, innovación educativa mediadas por las TICS, A finales de julio van a empezar la promoción.'),
(19, '1', '0', 1.00, 0.00, 1.00, 100.00, 'Se habilitó la plataforma Woouclap para el desarrollo de la docencia, Le han brindado acceso (creación de cuentas y capacitaciones) a los docentes.', '', '', ''),
(20, '0', '213', 0.00, 213.00, 213.00, 266.25, 'Con apoyo del departamento de Educación Virtual, se han desarrollado los siguientes recursos:\n114 videos, 35 OVAS, 26 podcast, 38 promociones de programa de la emisora digital.\nPara un total de 213 recursos digitales con ayuda de docentes.', '', '', ''),
(21, '74.8048%', '72%', 74.80, 72.00, 73.40, 734.02, '1054 docentes de 1406 utilizaron la plataforma de moodle durante el 2023-1\n1025 docentes utilizaron la plataforma SIVI-567 de 1416 durante el 2023-2', '', '', ''),
(22, '89.6552%', '90.3846%', 89.66, 90.38, 90.02, 128.60, 'En promedio 90% de docentes capacitados de primer ingreso en uso de las TIC', '', '', ''),
(23, '53.1295%', '99.8167%', 53.13, 99.82, 76.47, 152.95, '1284 estudiantes de primer ingreso capacitados en TIC sobre recursos institucionales como el SICVI del total de estudiantes de primer ingreso 2023-2 \n\nPara el segundo semestre se implementó un curso automatizado del manejo de los recursos institucionales como SICIVI-567 - En este curso participaron 894 estudiantes, los cuales lograron certificación. (total estudiantes matriculados en primer ingreso 2063)', '', '', ''),
(24, '27', '27', 27.00, 27.00, 54.00, 135.00, 'Semestre I. De acuerdo a las dinámicas de los procesos de capacitación desarrollados por el Departamento de Biblioteca se ejecutan un total de 27 capacitaciones dirigidas a estudiantes y docentes para un total de 674 personas capacitadas. En el mes de mayo no se reportan capacitaciones debido a que el Departamento de Biblioteca se encontraba en proceso de renovación de recursos digitales.\n\nSemestre II. Continuando con las actividades relacionadas a la capacitación de usuarios, desde el Departamento de Biblioteca se ejecutan un total de 27 sesiones en el periodo 2023-2 dirigidas a estudiantes y docentes para un total de 499 personas capacitadas. En el mes de mayo no se reportan capacitaciones debido a que el Departamento de Biblioteca se encontraba en proceso de renovación de recursos digitales, y en el mes de julio tampoco se registran por ser el periodo intersemestral.', 'Semestre I. De acuerdo a las dinámicas de los procesos de capacitación desarrollados por el Departamento de Biblioteca se ejecutan un total de 27 capacitaciones dirigidas a estudiantes y docentes para un total de 674 personas capacitadas. En el mes de mayo no se reportan capacitaciones debido a que el Departamento de Biblioteca se encontraba en proceso de renovación de recursos digitales.\n\nSemestre II. Continuando con las actividades relacionadas a la capacitación de usuarios, desde el Departamento de Biblioteca se ejecutan un total de 27 sesiones en el periodo 2023-2 dirigidas a estudiantes y docentes para un total de 499 personas capacitadas. En el mes de mayo no se reportan capacitaciones debido a que el Departamento de Biblioteca se encontraba en proceso de renovación de recursos digitales, y en el mes de julio tampoco se registran por ser el periodo intersemestral.', 'Durante el semestre 2023-2 hubo cese de actividades academicas para varios programas academicos, hecho que reduce las solicitudes de cursos de capacitación para usuarios.', 'Cada vez que sea contratado un recurso se prioriza la capacitación para el equipo de Bibliotecas.\nCuando el equipo se encuentra capacitado en el uso de nuevos recursos puede replicar el conocimiento adquirido a los demás usuarios de la Universidad.'),
(25, '69', '56', 69.00, 56.00, 125.00, 125.00, '125 trabajos y tesis para 2023 \n\nCon el animo de fortalecer las comunidades de Tesis y Trabajos de Grado en el Repositorio Institucional, el Departamento de Biblioteca mantiene una gestión y durante el periodo 2023-2 designo monitores y practicantes al desarrollo de actividades de publicación en ambas comunidades.', 'La resolución de designación de Personal de Apoyo Administrativo fue expedida para inicio de actividades el día 30 de octubre, por lo tanto solo a partir de esa fecha se contó con publicadores adicionales', 'En total se incluyeron 35 tesis y 64 trabajos de grado.', 'Para el 2024 se capacitara a personal de planta para la publicación de tesis y trabajos de grado en el repositorio una vez se finalice la catalogación de trabajos impresos.'),
(26, '0', '4', 0.00, 4.00, 4.00, 100.00, 'Se implementó un (1) Curso para Estudiantes sobre Inducción a Recursos Digitales Institucionales, Se implementó un (1) Curso para Docentes sobre el uso de la Plataforma de Gestión de Aprendizaje. \nSe desarrollaron dos (2) cursos tipo MOOC, uno de emprendimiento y el otro de talento humano', '', 'En proceso de formalización tenemos 2 cursos MOOC para trabajar con Emprendimiento y Regionalización.', ''),
(27, '1', '0', 1.00, 0.00, 1.00, 100.00, 'La radio digital ya tiene una plataforma inicial http://radio.uniatlantico.edu.co/ - Documento de creación de Radio Digital - Documento de Código de ética - Proyección de Resoluciónes (codigo de ético y creación de la emisora)\nA través de la Resolución Rectoral 003268 del 12 de diciembre del 2023 se crea el Sistema de Medios de la Universidad del Atlántico', '', '', ''),
(28, '0', '20', 0.00, 20.00, 20.00, 100.00, 'Se han iniciado los trabajos para la virtualización de Asignaturas de manera que en la Facultad de Ingenieria tenemos avances de 5 cursos y dos (2) cursos en Ciencias Básicas aunque falta la formalización de partes del Decano. \n\nSe desarrollaron e implementaron 20 cursos en plataforma: \nBalance de materia\nTrabajo de grado\nEstudio de Trabajo\nSeminario de Opciones de Grado\nLaboratorio de Creatividad\nHistoria III\nPsicología del Desarrollo Humano\n Cultura y Sociedad\nTecnologías aplicadas a los procesos inclusivos I\nGestión Tecnológica\nLectura para el desarrollo del pensamiento crítico\nPráctica Pedagógica Profesional en Lengua Castellana II\nAutomatización y control\nPolíticas Nutricionales Alimentarias\nManejo, empaque y conservación de productos agroindustriales\nQuímica general I\nDesafíos Impostergables de las ciencias sociales \nElectiva de Competencias Comunicativas para la Investigación en Educación Matemática\nÉtica y Política\nPráctica Pedagógica Profesional II', '', 'En proceso tenemos 30 asignaturas desde las diferentes Facultades', ''),
(29, '0', '0', 0.00, 0.00, 0.00, 0.00, 'Se trabajó en el 2023-1 en la Propuesta de ampliación de cobertura oferta academica de la Universidad del Atlántico presentado al Ministerio de Educación Nacional donde se cobijan nuevos programas y cupos para las Sedes Regionales. Debido a que en el 2022 no fue aprobado presupuesto para el estudio de pertincencia se trabajó esta propuesta con el visto bueno del MEN con base a fuentes secundarias: Conpes, planes de desarrollo nacional, departamental y municipales, estudidos cluster de la Camara de Cio y estudios del Agro de ADR. Finalmente este documento es la primera fase del estudio de pertinencia.\n\nNo ha sido aprobado se incluyó en el proyecto presentado al MEN (proyecto de transito) \nEl Estudio de Pertinencia de los programas académicos que ofrece de la Universidad del Atlántico en todas sus Sedes, incluyendo la Sede Regional Sur Suan y la Sede Regional Centro Sabanalarga, cuenta con presupuesto como proyecto 1 dentro del Proyecto PIC. Debe contratarse y poner en marcha en el 2024, teniendo en cuenta que el cierre para la contratación en la Universidad se dió anterior a la aprobación final por parte de todos los actores institucionales, MEN y Consejo Superior. En el mes de diciembre del 2023 e aportó lo adelantado por Regionalización al Departamento de Calidad Académica.', 'Falta de presupuesto interno para este estudio.', '', 'Continuar la segunda fase de la construcción del estudio de pertinencia con la ayuda de estudiantes de los programas de Economía y Administración de Empresas de la Universidad que estarán en modalidad de práticas en el 2023-2.'),
(30, '0', '1', 0.00, 1.00, 1.00, 100.00, 'Se obtuvo el nuevo registro calificado del programa de pregrado de Ingenieria en Agronegocios, articulado por ciclos propedéuticos con los programas de Técnica Profesional en Aprovechamiento de Residuos Agropecuarios y Tecnología de Transformación de Productos Agropecuarios, de la Facultad de Ingeniería por 7 años (Resolución 014341 de agosto 23 de 2023 otorgada por el Ministerio de Educación Nacional), con registro en las sedes de Puerto Colombia, Sede Regional Sur Suan y Sede Regional Centro Sabanalarga.', 'El ministerio está manejando unos tiempos muy largos en sus procesos.', '', ''),
(31, '0', '212', 0.00, 212.00, 212.00, 176.67, '2023-1:\nFacultad Número\nArquitectura 11\nBellas Artes \nCiencias Básicas 1\nCiencias Económicas \nCiencias Humanas \nCiencias Jurídicas \nEducación \nIngeniería 1\nNutrición \nQuímica y Farmacia \nTotal 13\n\n\n2023-2: \nFacultad Número\nArquitectura 57\nBellas Artes \nCiencias Básicas \nCiencias Económicas \nCiencias Humanas \nCiencias Jurídicas \nEducación 17\nIngeniería 17\nNutrición 108\nQuímica y Farmacia \nTotal 199\n\nTotal año: 212', 'Debido a la resolución de transito de tecnologo a profesional en Sede Norte, los estudiantes retrasan su grado para poder estar en estado de matriculado y así acceder a ese transito.', '', 'Para el 2023-2 se estará verificando el estado de los posibles aspirantes a grado y así realizar un acompañamiento personalizado que permita garantizar el proceso de grado. Se iniciará una revisión de la Resolución de transito actual.'),
(32, '0', '58', 0.00, 58.00, 58.00, 118.37, 'Se está realizando una encuesta en trabajo conjunto con la oficina de egresados.\n\nSe estructuró un instrumento de medición tipo encuesta en el 2023-1, conjuntamente con la oficina de egresados. Se inició la aplicación en el 2023-2, con una muestra de 244 encuestados de un Universo de 666 Egresados de programas Regionalizados del 2015 al 2022, se encontraron 58 egresados laborando.', 'Dificil comunicación egresados por desactualización de datos.', '', 'Garantizar la aplicación de la encuesta a la mayor parte de de egresados graduados.'),
(33, '0', '0', 0.00, 0.00, 0.00, 0.00, 'Se adelantaron reuniones con la facultad de ciencias economicas y la facultad de humanas para proyectar esta electiva. Así mismo, se prevee revisar la factiibilidad de este diseño de electiva para que sea una MOOC. \n\nSe propuso su inclusión en el proyecto enviado al MEN para la creación de programas virtuales incluyendo la catedra virtual de región.\n\nSe está trabajando en el diseño de la Electiva de Contexto Regional, se realizó el primer grupo focal con Docentes de la Universidad y se realizarán otros grupos focales en el 2024. Teniendo en cuenta que es una Electiva de Contexto transversal a todos los programas cuyo diseño implica estructurar el curriculo, transformarlo en OBA y/o contenidos virtuales coordinado conjuntamente con el Departamento de Virtualización, se espera finalizar en el 2024.', '', '', ''),
(34, '12', '13', 12.00, 13.00, 12.50, 138.89, 'DOCENTES EN REGION\n2023-1: \nFACULTAD DE EDUCACION\n1. Nazira santiago- lenguas - tco - F. Educación\n2. Edwin paz - lenguas - tco - F. Educación\n3. Ever Ortega- tco- c. Naturales F. Educación\n4. Sandra villamizar- tco- lic en matemáticas - F. Educación\n5. Jhonathan cervantes - Lic matematica - F. Educación\n\nF. Arquitectura\n1. Diana Fernández- documentación- tco - \n2. Carlos rada - expresión- tco - F. Arquitectura\n3. Cristian castro - construcción- tco - F. Arquitectura\nINGENIERIA\nAngie melendez - tco \nNUTRICION\nIngrid ballesteros - tco - nutrición \nFACULTAD DE CIENCIAS BASICAS \n1. Juancarlos marenco - mto - piscicultura \n2. Jonathan romero - mto - física F. Basicas\nTOTAL: 12\n2023-2: \nEDUCACION\n1. Nazira santiago- lenguas - tco - F. Educación\n2. Edwin paz - lenguas - tco - F. Educación\n3. Ever Ortega- tco- c. Naturales F. Educación\n4. Jhonathan cervantes - Lic matematica - F. Educación\n5. Sandra villamizar- tco- lic en matemáticas - F. Educación\nF. Arquitectura\n1. Diana Fernández- documentación- tco - \n2. Carlos rada - expresión- tco - F. Arquitectura\n3. Cristian castro - construcción- tco - F. Arquitectura\nINGENIERIA\n Angie melendez - tco - ingeniería \nNUTRICION\nIngrid ballesteros - tco - nutrición \nCIENCIAS BASICAS\n1. Jonathan romero - mto - física F. Basicas\n2. Verena Bayuelo Espitia (Coordinadora sede Suan del programa técnico en pisicultura continental)\n3. Ismael Piñeres (docentes de Fisica sede Suan) \nTOTAL: 13', '', '', ''),
(35, '0', '1', 0.00, 1.00, 1.00, 100.00, 'Se obtuvo el nuevo registro calificado del programa de pregrado de Ingenieria en Agronegocios, articulado por ciclos propedéuticos con los programas de Técnica Profesional en Aprovechamiento de Residuos Agropecuarios y Tecnología de Transformación de Productos Agropecuarios, de la Facultad de Ingeniería por 7 años (Resolución 014341 de agosto 23 de 2023 otorgada por el Ministerio de Educación Nacional)', 'El ministerio está manejando unos tiempos muy largos en sus procesos.', '', 'La facultad de Nutrición inicio la estructuración de su tercer ciclo llamado Seguridad Alimentaria, que se incluyó en la propuesta de ampliación de cobertura presentada al MEN.'),
(36, '1268', '1351', 1268.00, 1351.00, 1309.50, 119.05, 'En el 2023-1 se tuvieron 1.268 estudiantes matriculados en las sedes regionales de la Universidad según reporte del Departamento de Admisiones, con un total en la sede regional Sur Suan de 1.042; en la sede regional Centro Sabanalarga de 225 y en el CERES Sabanagrande de 1 estudiantes. Se detalla a continuación por Facultades: Arquitectura 174 en Suan y 50 en Sabanalarga, Ciencias Básicas 20 en Suan, Ciencias de la Educación 615 en Suan, 90 en Sabanalarga y 1 en Sabanagrande, Ingeniería 72 en Suan y 85 en Sabanalarga, y Nutrición y Dietética 161 en Suan. \n\nEn el semestre 2023-2, se tienen 1351 estudiantes matriculados en el 2023-2, 302 en la sede Sabanalarga y 1049 estudiantes en sede Suan', 'Por directriz de Vicerrectoría de Docencia hubo una disminución de cupos para algunos programas de la Universidad. En la sedes regionales se tuvieron en cuenta dificultades de consecución de docentes específicos, limitantes de uso de laboratorios en Sede Norte y previsión de sobreocupación de la sede en Suan.', '', 'Se esperan nuevas disposiciones del Gobierno Nacional con respecto al aumento de la cobertura en educación superior para el 2023- 2024 , con apoyo en recursos, de la mano del fortalecimiento financiero de la Universidad para las sedes regionales.'),
(37, '0', '1', 0.00, 1.00, 1.00, 100.00, 'Se realizaron reuniones con la Facultad de Educación y el Dpto de Calidad Academica para estructurar un proyecto de fortalecemiento de competencias básicas para el mejoramiento de Instituciones educativas del Departamento de Atlántico. \nSe realizó el Diseño del Proyecto "Juventud Atlántico a la UA", dentro del proyecto PIC, el cual tiene recursos y se pondrá en marcha en el 2024 junto con la Facultad de Ciencias de la Educación, para el mejoramiento de los resultados de las pruebas Saber 11 en las Instituciones de la Media de los municipios del Atlántico, con menor tasa de tránsito a la Educación Superior.', 'Materializar el proyecto por parte de la universidad y conseguir los recursos en el MEN para la ejecución', '', 'Concretar el proyecto.'),
(38, '0', '3', 0.00, 3.00, 3.00, 42.86, '2023-1 \nFacultad Número\nArquitectura 1\nBellas Artes \nCiencias Básicas \nCiencias Económicas \nCiencias Humanas \nCiencias Jurídicas \nEducación \nIngeniería \nNutrición \nQuímica y Farmacia \nTotal 1\n\n2023-2 \nFacultad Número\nArquitectura \nBellas Artes \nCiencias Básicas \nCiencias Económicas \nCiencias Humanas \nCiencias Jurídicas \nEducación \nIngeniería 1\nNutrición 1\nQuímica y Farmacia \nTotal 2\n\nTotal año: 3', 'Materializar el proyecto por parte de la universidad y conseguir los recursos en el MEN para la ejecución', 'Se realizaron reuniones con la Facultad de Educación y el Dpto de Calidad Academica para estructurar un proyecto de fortalecemiento de competencias básicas para el mejoramiento de Instituciones educativas del Departamento de Atlántico.', 'Concretar el proyecto.'),
(39, '146', '156', 146.00, 156.00, 151.00, 335.56, 'Número de estudiantes de la sede regional vinculados a Semilleros de Investigación\n2023-1 \nFacultad Número\nArquitectura 48\nBellas Artes \nCiencias Básicas 5\nCiencias Económicas \nCiencias Humanas \nCiencias Jurídicas \nEducación 28\nIngeniería 8\nNutrición 57\nQuímica y Farmacia \nTotal 146\n\n2023-2 \nFacultad Número\nArquitectura 57\nBellas Artes \nCiencias Básicas \nCiencias Económicas \nCiencias Humanas \nCiencias Jurídicas \nEducación 66\nIngeniería 33\nNutrición \nQuímica y Farmacia \nTotal 156\n\nTotal: 302', '', '', 'Incentivar a los estudiantes a vincularse a los semilleros.'),
(40, '32', '15', 32.00, 15.00, 47.00, 142.42, 'Número de estudiantes que desarrollan proyectos de innovación y/o emprendimiento\n\n2023-1 \nFacultad Número\nArquitectura 5\nBellas Artes \nCiencias Básicas \nCiencias Económicas \nCiencias Humanas \nCiencias Jurídicas \nEducación \nIngeniería 11\nNutrición 16\nQuímica y Farmacia \nTotal 32\n\n2023-2 \nFacultad Número\nArquitectura 15\nBellas Artes \nCiencias Básicas \nCiencias Económicas \nCiencias Humanas \nCiencias Jurídicas \nEducación \nIngeniería \nNutrición \nQuímica y Farmacia \nTotal 15\n\nTotal año: 47', 'Falta de continuidad de los proyectos y de concocatorias.', '', 'Aumentar la presencia de emprendimiento en las sedes regionales, buscar la posibilidad de tener un funcionario en sedes para la continuidad de los proyectos.'),
(41, '0', '0', 0.00, 0.00, 0.00, 0.00, 'Se ha participado en reuniones con la vicerrectoria de Extensión y Proyección para definir los criterios del diseño del Observatorio. \n\nEn el 2023-2, Se presentó la propuesta del Observatorio de Vida Académica y Universitaria en Región, a las distintas Facultades que tienen programas Regionalizados. Sin embargo no fue contratado el personal suficiente y por eso en el 2023 no fue posible diseñar este Observatorio. Así mismo no se contó con ningún tipo de recurso.', '', '', ''),
(42, '0', '0', 0.00, 0.00, 0.00, 0.00, 'El documento borrador correspondiente a la politica esta elaborado, pero se encuentra en ajustes para entrega a la Oficina de Juridica, para luego pasar al Consejo Académico para su respectiva aprobación y finalmente al Consejo Superior\n\nEl documento se encuentra en modificación nuevamente por observaciones realizadas por el jefe de planeación y se tiene pendiente una reunión con la Vicerrectoría Financiera.', '', '', ''),
(43, '1', '0', 1.00, 0.00, 1.00, 100.00, 'Acto administrativo elaborado (Resolución 001 del 16 de marzo de 2023), emitida por el Decano previa aprobación del Concejo de Facultad de Ciencias Humanas, correspondiente a la conformación del Comité de Planeación Lingüística en Lenguas Nativas', '', '', ''),
(44, '0', '52', 0.00, 52.00, 52.00, 130.00, 'Se van hacer alianzas o carta de intención a los colegios públicos o privados con población con discapacidad para socializar la oferta académica de la Universidad\n\nNúmero de estudiantes con discapacidad beneficiarios del convenio con el colegio Salvador Suarez Suarez:\n52 Estudiantes hasta el momento.', '', '', ''),
(45, '1', '0', 1.00, 0.00, 1.00, 100.00, 'Se realizó un informe sobre las necesidades de las oficinas del Programa DIVERSER, el cual fue aprobado por el Vicerrector de Docencia.\nEl documento fue entregado a la Oficina de Planeación, y nos encontramos a la espera de respuesta.\nVer anexo (INFORME DE NECESIDADES DELAS OFICINAS DEL PROGRAMA DIVERSERDE LA VICERRECTORIA DE\nDOCENCIAPARAADECUACION DEL ESPACIO FISICO)', '', '', ''),
(46, '121', '119', 121.00, 119.00, 240.00, 100.00, '240 videos en LSC publicados en la pagina web de la Universidad en Biblioteca digital', '', '', ''),
(47, '0', '140', 0.00, 140.00, 140.00, 140.00, '140 materiales accesibles (audio libros y videos en lengua de señas)', '', '', ''),
(48, '0%', '0%', 0.00, 0.00, 0.00, 0.00, 'El equipo de Diverser se ha venido reuniendo con el Departamento de Calidad, y en dichas reuniones ha realizado aportes al documento de la politica y lineamientos de modelo curricular desde un enfoque emergente integrador e interdisciplinar de la Universidad del Atlántico\n\nSe realizó una reunión con los Coordinadores misionales de cada facultad, Jefe del Departamento de Calidad Académica y el Secretario Tecnico del Comite Curricular con el fin de conformar el equipo de trabajo y la ruta para la resignificación de los programas con enfoque inclusivo e intercultural.\nSe construyó documento de Instrumento diagnostico de enfloque inclusivo en los programas academicos, el cual se encuentra en validación.', '', '', ''),
(49, '11', '274', 11.00, 274.00, 285.00, 285.00, 'N° de docentes certificados en temáticas relacionadas con educación inclusiva, interculturalidad y pluridiversidad\n \n2023-1 \nFacultad Número\nArquitectura \nBellas Artes \nCiencias Básicas \nCiencias Económicas \nCiencias Humanas \nCiencias Jurídicas \nEducación 9\nIngeniería \nNutrición 2\nQuímica y Farmacia \nTotal 11\n\n2023-2 \nFacultad Número\nArquitectura 11\nBellas Artes 41\nCiencias Básicas 26\nCiencias Económicas 29\nCiencias Humanas 18\nCiencias Jurídicas 12\nEducación 82\nIngeniería 16\nNutrición 28\nQuímica y Farmacia 11\nTotal 274\n\nTotal año: 285', '', '', ''),
(50, '0', '285', 0.00, 285.00, 285.00, 190.00, '285 estudiantes capacitados en inclusión y lengua de señas, estudiantes de educación infantil, licenciatura en humanidades y lengua de señas, administración de empresas (electiva en educación inclusion y diversidad: 57 estudiantes). De los 285 estudiantes capacitados 228 fueron capacitados en lenguas de señas y 57 en inclusión', '', '', 'Se requiere activar la electiva de discapacidad y sociedad'),
(51, '0', '40', 0.00, 40.00, 40.00, 100.00, '40 administrativos capacitados en lengua de señas colombianas', '', '', ''),
(52, '100%', '0%', 100.00, 0.00, 100.00, 100.00, '42/42 estudiantes capacitados en Tifloctecnologia', '', '', ''),
(53, '0', '0', 0.00, 0.00, 0.00, 0.00, 'Se debe actualizar el Acuerdo Superior 000001 del 12 de marzo del 2018: puntaje, selección, inscripcion y acceso \nIncluir a los excombatientes, transito a la vida civil y los Rroom', '', '', 'Debe presentarse antes a la jefe de oficina de juridica, al consejo académico y luego al consejo superior a través de un consejero (solicitar apoyo al vicerrector de bienestar)'),
(54, '1', '0', 1.00, 0.00, 1.00, 100.00, 'Se tiene diseñado y aprobado un diplomado en Lengua de Señas Colombianas', '', '', ''),
(55, '0', '0', 0.00, 0.00, 0.00, 0.00, 'La propuesta del acto administrativo (resolución rectoral) ya fue revisado por la Oficina de Jurídica.\nActualmente, se encuentra en revisión por parte del equipo asesor de la Vicerrectoría de Docencia para presentarlo al Rector para su firma.\nCon corte a 30 de diciembre de 2023, el documento aún se encuentra en revisión por parte del equipo asesor de la Vicerrectoría de Docencia. Estamos a la espera del VoBo de este para proceder al envío al Sr. Rector.', '', '', 'Se deben hacer todas las acciones pertinentes para que el actoa administrativo sea aprobado a más tardar en el mes de septiembre para asi poder lograr la implementacion de algunos componentes del sistema'),
(56, '0%', '0%', 0.00, 0.00, 0.00, 0.00, 'La propuesta del acto administrativo ya fue revisado por la Oficina de Jurídica. Se está gestionando la posibilidad de desarrollarlo a través de un proyecto de investigación (opción de grado de la Maestría en Gestión de la Calidad)\nCon corte a 30 de diciembre de 2023, continuamos a la espera del VoBo del Sr Vicerrector de Docencia para poder implementar el sistema', 'El Vicerrector lo está consultando con asesores.', '', ''),
(57, '55.5556%', '47.3%', 55.56, 47.30, 47.30, 82.98, 'En el primer semestre del año 2023 se recibió de parte del MEN las resoluciones de acreditación de los programas de pregrado Contaduría Pública (25 mayo 2023 Res 008575) y Economía (8 mayo 2023 Res 007566), por lo cual ya son 25 los programas acreditados en relación a los 45 acreditables.\n\nSe recibió la Acreditación por primera. vez del Doctorado en Educación. - RUDECOLOMBIA', 'El porcentaje varia de acuerdo al número de programas acreditables, lo cual depende de los años de funcionamiento de los programas', '', ''),
(58, '2', '1', 2.00, 1.00, 3.00, 100.00, 'En el primer semestre del año 2023 se recibió de parte del MEN las resoluciones de acreditación de los programas de pregrado Contaduría Pública (25 mayo Res 008575) y Economía (8 mayo Res 007566)\n\n Se recibió la Acreditación por primera. vez del Doctorado en Educación. - RUDECOLOMBIA (Resolución 016903 del 20 de septiembre del 2023)', '', '', ''),
(59, '0', '0', 0.00, 0.00, 0.00, 0.00, 'Se vienen realizando reuniones por parte del equipo de trabajo delegado por el Vicerrector de Docencia, para la revisión de los estímulos, reconocimientos y distinciones a estudiantes, docentes y egresados.\nSe ha revisado las normativas institucionales, como los Estatutos Docente, Estatutos Estudiantil y la Politica de Egresados, para unificarlos y desarrollar un solo documento que incluya los tres estamentos.', '', '', ''),
(60, '0', '0', 0.00, 0.00, 0.00, 0.00, 'El nuevo módulo responsabilidad y vinculación docente del sistema académico aportó a este proyecto porque ya la información de talento humano está registrada y articulada con el módulo académico. Ahora se pretende coordinar con Talento Humano para registrar la información de la producción académica de los docentes.', '', '', 'Reuniones con Talento Humano para coordinar el registro de la producción académica.'),
(61, '1', '0', 1.00, 0.00, 1.00, 100.00, 'Se está realizando un comparativo de la distribucción de horas de los docentes para los procesos misionales, a partir de los PTA semestrales.\n\nGracias a la adquisición del nuevo módulo de Academusoft: RVD se logró tener sistematizado el Plan de Trabajo Académico de los docentes', '', '', ''),
(62, '1', '0', 1.00, 0.00, 1.00, 100.00, 'En el periodo 2023 se estudió los distinto reglamentos que cuenta actualmente el Departamento de postgrado y se elaboró dos propuestas encaminadas a actualizar y mejorar dos procesos fundamentales que son el reglamento estudiantil donde se actualizo algunos artículos y la propuesta de oferta de sostenibilidad de los programas de postgrado cuyo objetivo es mejorar el manejo financiero de los mismos. Las dos propuestas fueron enviadas a la Vicedocencia para su respectiva revisión el 15 de noviembre del 2023.', '', '', ''),
(63, '3', '4', 3.00, 4.00, 7.00, 100.00, 'F. Educación: Maestría en Pedagogía Lengua Materna y la Maestría en lectura y escritura con enfansis en Lengua Materna \n- Maestría en Educación Física -Deporte\n\n\nF.Ciencias Humanas: Maestria en Interculturalidad e intervención social opcional\nInterprete de Lengua de Señas Colombia\n\n\nF. Derecho: Esp Penal y Casación \nF. Ingeniería: Doctorado en Ingeniería', '', '', ''),
(64, '2', '1', 2.00, 1.00, 3.00, 100.00, 'Ya el MEN dio aprobación de los registros calificados de la Maestría en Economía (9 feb 2023 Res 001754) y Maestría en Contabilidad (28 feb 2023 Res 3426)\n\nMaestría en Administración de Empresas (014384 de 24 agosto de 2023)', '', '', ''),
(65, '0', '0', 0.00, 0.00, 0.00, 0.00, 'La propuesta del acto administrativo ya fue realizada y expuesta al rector para su firma', '', '', ''),
(66, '0', '0', 0.00, 0.00, 0.00, 0.00, 'Se ha avanzado en el documento maestro de medicina y se espera radicar en los meses de junio y julio. Pero la alta dirección no ha definido la creación de la facultad.\nCon corte a 30 de diciembre de 2023, se informa que el documento del programa de medicina, ya fue radicado ante el MEN en el mes de noviembre, se está trabajando en lo pertinente para la creación de la facultad', '', '', ''),
(67, '0', '1', 0.00, 1.00, 1.00, 100.00, 'Se está trabajando en cuatros convenios: 1) Convenio con Bancomeva: el contrato esta en jurídica para su revisión. 2) Convenio con la Alcaldía de Barranquilla: se envió carta de intención al área encargada en la Alcaldía para su revisión y aprobación. 3) Convenio con Procaps: se realizó una primera reunión con los directivos de dicha empresa, la encargada de Postgrado y la coordinadora de la Maestría en Gestión Farmaceútica el día 6 de mayo del 2023. 4) Convenio con la Alcaldía de Malambo: se realizó un primer encuentro con los directivos y el personal de postgrado.\nEn el mes de octubre se firmó el Convenio de cooperación interinstitucional entre la Alcaldía Distrital de Barranquilla y el Departamento de Postgrados de la Universidad del Atlántico con el objeto de ofrecer el servicio de educación posgradual en los diferentes programas académicos y modalidades que oferta nuestra Institución, los cuales se encuentran debidamente aprobados por el Ministerio de Educación Nacional.\n\nEl convenio de Cooperación Interinstitucional otorgará a los empleados y familiares hasta primer grado de consanguinidad, cónyuge o compañero(a) permanente, de la ALCALDÍA DE BARRANQUILLA, los porcentajes de descuentos del valor de las matrículas durante la vigencia del presente convenio, de la siguiente manera: 10% de descuento sobre el valor total del semestre. El convenio tendrá una duración de un año a partir de la firma del convenio, y podrá ser prorrogado únicamente si las partes manifiestan por escrito y con no menos de treinta (30) días de anticipación a la fecha de terminación su intención de renovación.', '', '', ''),
(68, '0', '0', 0.00, 0.00, 0.00, 0.00, 'Se tiene una propuesta entregada al comité curricular central para luego pasarlo al académico y luego al superior\n\nSe sustentó en el CCC y se estan trabajando mesas por temáticas', '', '', ''),
(69, '0', '0', 0.00, 0.00, 0.00, 0.00, 'Se adelantaron unas reuniones con planeación se definieron unos contenidos mínimos y se está procediendo a desarrollar cada uno\n\n\nCon corte a 30 dic, el documento se encuentra finalizado y está ne proceso que en el orden del día de un consejo académico para ser presentado.', '', '', ''),
(70, '8.6194%', '0%', 8.62, 0.00, 8.62, 172.39, '359 materias o asignaturas relacionadas de 4165 asignaturas totales en pregrado', '', '', ''),
(71, '0', '6', 0.00, 6.00, 6.00, 40.00, 'Apenas desde Extensión y Proyección Social están creando el programa de Voluntariado a través de una resolución rectoral. No obstante, en algunas asignaturas se desarrollan proyectos de aula tipo voluntariado, por ejemplo: proyectos urbanísticos, desarrollo del barrio, etc.\n\n6 programas académicos tienen 6 proyectos de voluntariado de las siguientes facultades:\nF.Educación: 2\nF.Bellas Artes: 2\nF. Ciencias Humanas: 1\nF. de Nutrición y Dietetica: 1', '', '', ''),
(72, '57%', '60%', 57.00, 60.00, 60.00, 95.24, 'Aún no se tiene el promedio con los resultados del 2023 (se tendrá en diciembre), por lo cual se reporta con respecto al 2020, 2021, 2022\nCon corte a 30 de dic, se informa que esta información sale aproximadamente para febrero del 2024 y no podrá ser medido', '', '', ''),
(73, '150', '0', 150.00, 0.00, 150.00, 96.77, 'Aún no se tiene el promedio con los resultados del 2023 (se tendrá en diciembre), por lo cual se reporta con respecto al 2020, 2021, 2022\nCon corte a 30 de dic, se informa que esta información sale aproximadamente para febrero del 2024 y no podrá ser medido', '', '', ''),
(74, '0', '0', 0.00, 0.00, 0.00, 0.00, 'Se continuan con las reuniones de adecuación de los instrumentos, se va a aplicar enuesta a ciertos docentes para recibir retroalimentación del diseño del cuestionario. Por otro lado se va promediar los resultados de las 3 encuestas para identiifcar el estadístico de posición en relación a toda la población.', '', '', ''),
(75, '1', '8', 1.00, 8.00, 9.00, 90.00, 'Se han realizado reuniones con los delegados de calidad de las facultades, para sensibilizar la manera de realizar el informe anual. La facultad de Arquitectura envío el informe del estudio de impacto de las estrategias académico administrativas de los programas en región.\nLas siguientes facultades enviaron el informe: Educación, Ingeniería, Nutrición y Ciencias Humanas, Ciencias Básicas, Bellas Artes, Ciencias económicas y Química y Farmacia.\nTotal: 9', '', '', ''),
(76, '30%', '33%', 30.00, 33.00, 31.50, 180.00, 'La tasa de acumulacion de grado desde el 20131-2023-1 fueron 33%, de acuerdo a la formula del MEN', '', '', ''),
(77, '0', '0', 0.00, 0.00, 0.00, 0.00, 'Con corte a 30 de dicembre, se está trabjando en un borrador', 'No se tiene avance al respecto', '', ''),
(78, '0', '1', 0.00, 1.00, 1.00, 100.00, 'Se tiene consolidado un reporte con estadisticas actualizadas de acuerdo a las opciones de grado de cada facultad comparando los avances con respecto al 2020', '', '', ''),
(79, '0', '0', 0.00, 0.00, 0.00, 0.00, 'Esta politica será incluida en la actualización de la normativa del concurso docente 2024', '', '', 'Agregar principios a la política de meritocracia.\n- Revisar si la política de meritocracia va aplicar sola para el acceso a la carrera profesoral docente, o si también para la permanencia, evaluación y retiro.'),
(80, '0', '0', 0.00, 0.00, 0.00, 0.00, 'Esta politica será incluida en la actualización de la normativa del concurso docente 2024', '', '', ''),
