-- ═════════════════════════════════════════════════════════════════════════════
-- PLAN DE ACCIÓN 2023 COMPLETO: crea el formulario "Plan de Acción 2023" y carga la FORMULACIÓN y el SEGUIMIENTO
-- del "FOR-DE-144 Consolidado Plan de acción 2023.xlsx".
--   · 233 indicadores y su distribución por facultades.
--   · SEGUIMIENTO: semestre 1 del Excel → trimestre 2 (T2) y semestre 2 → trimestre 4 (T4); T1 y T3 quedan vacíos.
--     Con logros, límites, observación, acciones de fortalecimiento y el seguimiento de cada facultad.
--
-- Cómo usarlo:
--   1. Haz un respaldo de la base de datos.
--   2. Ejecuta TODO el archivo de una vez (usa variables @).
--   3. Si el formulario "Plan de Acción 2023" ya tiene indicadores, NO carga nada (evita duplicar) y lo avisa en el primer SELECT.
--   4. @ef = estado de la formulación:  2 = PUBLICADOS (aparecen en Seguimiento) ← por defecto;  0 = borradores.
--      @es = estado de los 4 trimestres del seguimiento:  2 = APROBADOS (corte cerrado) ← por defecto;  0 = borradores.
-- ═════════════════════════════════════════════════════════════════════════════
SET NAMES utf8mb4;
SET @ef = 2;
SET @es = 2;
SET @anio = 2023;

-- 1) Formulario (se crea si no existe)
SELECT 'Plan de Acción 2023', 'FOR-DE-144 Plan de acción 2023', 'libre', NULL, NULL, 1, 2023
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM formularios WHERE titulo LIKE 'Plan de Acci%n 2023%');
SET @formulario = (SELECT id FROM formularios WHERE titulo LIKE 'Plan de Acci%n 2023%' ORDER BY id DESC LIMIT 1);
SET @ya = (SELECT COUNT(*) FROM formulacion_144 WHERE formulario_id = @formulario);
SET @base = (SELECT COALESCE(MAX(id), 0) FROM formulacion_144);
SELECT @formulario AS formulario_id, (SELECT titulo FROM formularios WHERE id = @formulario) AS titulo, @ya AS indicadores_que_ya_tenia,
       IF(@ya = 0, 'Todo en orden: se cargará la formulación y el seguimiento', 'NO SE CARGA NADA: el formulario ya tiene indicadores') AS mensaje;

-- 2) Tabla de apoyo: nombre EXACTO del catálogo (por código L1-M1-P1) para línea, objetivo, motor y proyecto. Si un código no existe se usa el texto del Excel.
DROP TABLE IF EXISTS tmp_lmp_2023;
CREATE TABLE tmp_lmp_2023 (lc VARCHAR(10), mc VARCHAR(10), pc VARCHAR(10), linea VARCHAR(500), objetivo TEXT, motor VARCHAR(500), proyecto VARCHAR(600)) DEFAULT CHARSET=utf8mb4;

-- Revisa qué nombre quedó para cada código (si alguno salió del Excel es que no estaba en el catálogo):
SELECT t.lc, t.mc, t.pc, t.linea, t.motor, t.proyecto FROM tmp_lmp_2023 t ORDER BY t.lc, t.mc, t.pc;

-- 3) Formulación (primero a una tabla temporal; solo pasa a formulacion_144 si el formulario estaba vacío)
DROP TABLE IF EXISTS tmp_form_2023;
CREATE TABLE tmp_form_2023 LIKE formulacion_144;

START TRANSACTION;
SELECT id, formulario_id, nombre_borrador, anio, linea_estrategica, objetivo, estrategia, motor_desarrollo, meta_resultado, proyecto, ponderacion_proyectos, actividad_proyecto, ponderacion_actividades, responsable_formulacion, id_indicador, gestionado_facultades, nombre_indicador, formula_medicion, frecuencia_medicion, unidad_medida, tipo_medicion, descripcion_indicador, planes_institucionales, linea_base_meta, anio_base_meta, meta_s1, meta_s2, meta_programada, estado_formulacion, estado_seguimiento, solicitud_estado_formulacion, solicitud_estado_seguimiento, semaforo_etapa_formulacion, semaforo_etapa_seguimiento, semaforo_rechazo_etapa_formulacion, semaforo_rechazo_etapa_seguimiento, fecha_publicacion_formulacion, creado_por FROM tmp_form_2023 WHERE @ya = 0;

-- 4) Seguimiento de cada indicador: S1 → T2 y S2 → T4
DROP TABLE IF EXISTS tmp_seg_2023;
CREATE TABLE tmp_seg_2023 (n INT PRIMARY KEY, t2 VARCHAR(40), t4 VARCHAR(40), s1 DECIMAL(14,2) NULL, s2 DECIMAL(14,2) NULL,
                           ejecutada DECIMAL(14,2), avance DECIMAL(14,2), logros TEXT, limites TEXT, observacion TEXT, acciones TEXT) DEFAULT CHARSET=utf8mb4;

UPDATE formulacion_144 f JOIN tmp_seg_2023 s ON f.id = @base + s.n
SET f.trimestre1_seguimiento = NULL, f.trimestre2_seguimiento = s.t2, f.trimestre3_seguimiento = NULL, f.trimestre4_seguimiento = s.t4,
    f.semestre1_seguimiento = s.s1, f.semestre2_seguimiento = s.s2, f.meta_ejecutada = s.ejecutada, f.porcentaje_avance = s.avance,
    f.logros = s.logros, f.limites = s.limites, f.observacion_estado = s.observacion, f.acciones_fortalecimiento = s.acciones,
    f.estado_seguimiento = @es, f.solicitud_estado_seguimiento = IF(@es = 2, 1, 0), f.semaforo_etapa_seguimiento = IF(@es = 2, 4, 0),
    f.semaforo_rechazo_etapa_seguimiento = 0, f.fecha_publicacion_seguimiento = IF(@es = 2, NOW(), NULL)
WHERE @ya = 0 AND f.formulario_id = @formulario;

-- Estado de cada trimestre (el seguimiento se aprueba por trimestre)
CREATE TABLE IF NOT EXISTS seguimiento_trimestres_144 (
    formulacion_id INT NOT NULL, trimestre TINYINT NOT NULL, estado TINYINT NOT NULL DEFAULT 0, solicitud TINYINT NOT NULL DEFAULT 0,
    semaforo_etapa TINYINT NOT NULL DEFAULT 0, semaforo_rechazo_etapa TINYINT NOT NULL DEFAULT 0, fecha_publicacion DATETIME NULL,
    fecha_actualizacion DATETIME NULL, PRIMARY KEY (formulacion_id, trimestre)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
SELECT f.id, t.n, @es, IF(@es = 2, 1, 0), IF(@es = 2, 4, 0), 0, IF(@es = 2, NOW(), NULL), NOW()
FROM formulacion_144 f
JOIN (SELECT 1 AS n UNION SELECT 2 UNION SELECT 3 UNION SELECT 4) t
WHERE @ya = 0 AND f.formulario_id = @formulario AND f.id BETWEEN @base + 1 AND @base + 233
ON DUPLICATE KEY UPDATE estado = VALUES(estado), solicitud = VALUES(solicitud), semaforo_etapa = VALUES(semaforo_etapa),
                        semaforo_rechazo_etapa = 0, fecha_publicacion = VALUES(fecha_publicacion), fecha_actualizacion = NOW();

-- 5) Distribución por facultades (lo concertado en la formulación) y seguimiento de cada facultad. La facultad se busca por nombre.
DROP TABLE IF EXISTS tmp_fac_2023;
CREATE TABLE tmp_fac_2023 (n INT, facultad VARCHAR(60), dist DECIMAL(14,2), s1 DECIMAL(14,2) NULL, s2 DECIMAL(14,2) NULL, descripcion TEXT NULL) DEFAULT CHARSET=utf8mb4;

SELECT @base + g.n, (SELECT fa.id FROM facultades fa WHERE fa.nombre LIKE CONCAT('%', g.facultad, '%') ORDER BY fa.id LIMIT 1), '', g.dist, g.s1, g.s2, g.descripcion
FROM tmp_fac_2023 g
WHERE @ya = 0 AND (SELECT fa.id FROM facultades fa WHERE fa.nombre LIKE CONCAT('%', g.facultad, '%') ORDER BY fa.id LIMIT 1) IS NOT NULL
ON DUPLICATE KEY UPDATE distribucion = VALUES(distribucion), seguimiento_sem1 = VALUES(seguimiento_sem1), seguimiento_sem2 = VALUES(seguimiento_sem2),
                        seguimiento_descripcion = VALUES(seguimiento_descripcion);
COMMIT;

DROP TABLE IF EXISTS tmp_lmp_2023;
DROP TABLE IF EXISTS tmp_form_2023;
DROP TABLE IF EXISTS tmp_seg_2023;
DROP TABLE IF EXISTS tmp_fac_2023;

-- Verificación (debe dar 233 indicadores y 4 trimestres cada uno):
SELECT COUNT(*) AS indicadores_con_trimestres, MIN(c) AS min_trimestres, MAX(c) AS max_trimestres
FROM (SELECT formulacion_id, COUNT(*) AS c FROM seguimiento_trimestres_144 WHERE formulacion_id IN (SELECT id FROM formulacion_144 WHERE formulario_id = @formulario) GROUP BY formulacion_id) x;
-- Otras comprobaciones (no deben devolver filas):
--   SELECT * FROM formulacion_distribucion_facultad_144 WHERE formulacion_id IN (SELECT id FROM formulacion_144 WHERE formulario_id = @formulario) AND facultad_id IS NULL;
--   SELECT DISTINCT responsable_formulacion FROM formulacion_144 WHERE formulario_id = @formulario AND responsable_formulacion NOT IN (SELECT nombre FROM cargos);
